#!/bin/sh
# Back up everything that cannot be rebuilt from the repository: the PostgreSQL
# database and the n8n configuration volume. Images, containers and the .env are
# excluded; .env is regenerated by configure.py and must never land in a backup
# directory that might be synced somewhere.
#
#   sh scripts/backup.sh [destination-directory]
#
# Verify a backup with scripts/restore.sh against a throwaway database before
# trusting it. An untested backup is not a backup.
#
# On Git Bash for Windows, run it as:
#   MSYS_NO_PATHCONV=1 sh scripts/backup.sh
# MSYS rewrites container paths such as /data into Windows paths otherwise. The
# target for this script is the Linux host, where no such workaround is needed.

set -eu

DEST=${1:-./backups}
STAMP=$(date -u +%Y%m%dT%H%M%SZ)
DIR="$DEST/$STAMP"
PROJECT=${COMPOSE_PROJECT_NAME:-clientflow-ai}

mkdir -p "$DIR"

echo "Backing up to $DIR"

# Database. --clean --if-exists makes the dump replayable over an existing
# schema; the custom format allows selective restore and parallel loading.
docker exec "${PROJECT}-db-1" pg_dump -U clientflow -d clientflow \
    --format=custom --clean --if-exists > "$DIR/clientflow.dump"
echo "  database: $(wc -c < "$DIR/clientflow.dump") bytes"

# n8n configuration volume, which holds the imported workflows and the
# credentials n8n encrypts with N8N_ENCRYPTION_KEY. The dump is useless without
# that key, so record which .env it belongs to.
docker run --rm \
    -v "${PROJECT}_n8n_data:/data:ro" \
    -v "$(cd "$DIR" && pwd):/backup" \
    alpine:3.20 tar czf /backup/n8n_data.tar.gz -C /data .
echo "  n8n volume: $(wc -c < "$DIR/n8n_data.tar.gz") bytes"

cat > "$DIR/MANIFEST.txt" <<EOF
ClientFlow backup
taken_at_utc: $STAMP
compose_project: $PROJECT
contents:
  clientflow.dump  pg_dump custom format, restore with scripts/restore.sh
  n8n_data.tar.gz  n8n volume; needs the same N8N_ENCRYPTION_KEY to decrypt credentials
not included:
  .env and local-secrets/, which are regenerated by scripts/configure.py
  docker images, which are rebuilt from the repository
EOF

echo "Done. Verify it with: sh scripts/restore.sh $DIR --verify"
